@'
from pathlib import Path
import re
root = Path(r'D:\kpmyrepo\AISDLC-Assignment1\Part-1B')
spec = (root / 'specs' / '001-support-email-triage' / 'spec.md').read_text(encoding='utf-8')
section = spec.split('### Traceability Matrix', 1)[1].split('### Evaluation Control', 1)[0]
rows = []
for line in section.splitlines():
    m = re.match(r'^\| ([^|]+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \|$', line)
    if m and m.group(1).strip() != 'ID': rows.append(tuple(x.strip() for x in m.groups()))
ids = [r[0] for r in rows]
duplicates = sorted({x for x in ids if ids.count(x) > 1})
manual_ids = ['INV-SIMPLE-01','GR-EVAL-01','GR-EVAL-02','GR-TRACE-01','GR-EVAL-03','GR-GOV-01','GR-GOV-03','GR-GOV-02']
manual_missing = [x for x in manual_ids if not any(r[0] == x and r[2] == 'manual checklist item recorded in the harness log' for r in rows)]
case_table = spec.split('### Evaluation Dataset v1',1)[1].split('### Traceability Matrix',1)[0]
cases = re.findall(r'^\| (CASE-\d{2}) \| ([^|]+) \| ([^|]+) \|$', case_table, re.M)
errors = []
if duplicates: errors.append('duplicate IDs: ' + ','.join(duplicates))
if any(r[3] != 'pending' for r in rows): errors.append('non-pending traceability result')
if manual_missing: errors.append('manual review/control mappings missing exact phrase: ' + ','.join(manual_missing))
if len(cases) != 18 or len({c[0] for c in cases}) != len(cases): errors.append('dataset case IDs/count invalid')
if any(not c[2].strip() for c in cases): errors.append('empty traces_to')
fields = re.findall(r'^\| `([^`]+)` \|', spec.split('### Stable Output Contract',1)[1].split('### Priority Rubric',1)[0], re.M)
if len(fields) != 8: errors.append(f'expected eight contract fields, found {len(fields)}')
if errors:
    print('FAIL\n' + '\n'.join(errors))
else:
    print(f'PASS: {len(rows)} unique traceability rows, all pending; {len(cases)} uniquely identified cases with traces_to; all review/control rows use required wording; 8 output fields.')
